from robot.utils.robottime import timestr_to_secs

from ..interfaces.base import BaseInterface
from .trigger import FaultTrigger
from ..converter import to_int


class FaultGenerationInterface(BaseInterface):

    def send_hwapi_api_alarm_msg(self, sender, receiver, fault_id, unit_id, *optional_fault_paramteters, **kwargs):
        """Send HWAPI api alarm message.

        :param integer sender: Sender SIC address.
        :param integer receiver: Receiver SIC address.
        :param integer fault_id: Fault ID.
        :param integer unit_id: Faulty unit ID.
        :param float timeout: Time to wait for positive procedure result (via kwargs).
        :param string alias: Name of execution context (via kwargs).
        """
        sender = to_int(sender)
        receiver = to_int(receiver)
        fault_id = to_int(fault_id)
        unit_id = to_int(unit_id)
        fault_params = [to_int(f) for f in optional_fault_paramteters]

        timeout = timestr_to_secs(kwargs.get("timeout", 10))
        alias = kwargs.get("alias", "default")

        FaultTrigger(self.store.get(alias), timeout).send_hwapi_api_alarm_msg(sender, receiver, fault_id, unit_id, *fault_params)

